import { AxiosRequestConfig } from 'axios';
export interface EnhancedAxiosOptions {
    headers: [{
        [key: string]: string;
    }];
}
export interface CustomAxiosRequestConfig extends AxiosRequestConfig {
    retry?: boolean;
}
export interface UserInfoToken {
    iss: string;
    exp: string;
    nbf: number;
    aud: string;
    sub: string;
    country: string;
    serviceModel: string;
    vendorId?: string;
    governmentId: string;
    preferredLanguage: string;
    email: string;
    name: string;
    given_name: string;
    family_name: string;
    app: string;
    tid: string;
    nonce: string;
    azp: string;
    createdOn: string;
    ver: string;
    iat: number;
    role: string;
    roles: Array<string>;
    extension_tncaccepteddatetime: number;
    scopes: Array<string>;
    segmentation: Array<string>;
    distributionCenterIds?: Array<string>;
    supportedCountries?: Array<string>;
    isFederated?: boolean;
}
export interface UserCountryAndLanguage {
    user_country: string | null;
    language: string;
    base_url: string;
}
export interface AuthData {
    [key: string]: string | null;
}
